using System.Text.Json;using Microsoft.AspNetCore.Identity;using Microsoft.EntityFrameworkCore;using Peletnapechkai.Api.Domain.Auditing;using Peletnapechkai.Api.Domain.Identity;using Peletnapechkai.Api.Domain.Knowledge;using Peletnapechkai.Api.Infrastructure.Identity;using Peletnapechkai.Api.Infrastructure.Persistence;
namespace Peletnapechkai.Api.Endpoints;
public static class KnowledgeEndpoints{public static IEndpointRouteBuilder MapKnowledgeEndpoints(this IEndpointRouteBuilder e){var g=e.MapGroup("/api/v1/admin/knowledge").RequireAuthorization(AuthorizationPolicies.ManageEditorial).WithTags("Knowledge Vault");g.MapGet("/",List);g.MapPost("/",Create).ValidateAntiforgery();g.MapPost("/{id:guid}/approve",(Guid id,System.Security.Claims.ClaimsPrincipal p,UserManager<ApplicationUser>u,PublishingDbContext d,CancellationToken t)=>Review(id,true,p,u,d,t)).ValidateAntiforgery();g.MapPost("/{id:guid}/reject",(Guid id,System.Security.Claims.ClaimsPrincipal p,UserManager<ApplicationUser>u,PublishingDbContext d,CancellationToken t)=>Review(id,false,p,u,d,t)).ValidateAntiforgery();return e;}
 private static async Task<IResult>List(PublishingDbContext d,CancellationToken t)=>Results.Ok(await d.KnowledgeCandidates.AsNoTracking().OrderByDescending(x=>x.UpdatedAt).Take(200).Select(x=>new{x.Id,locale=x.Locale.Code,x.Title,x.Claim,x.SourceUrl,x.AiAssisted,status=x.Status.ToString(),x.CreatedAt,x.UpdatedAt}).ToListAsync(t));
 private static async Task<IResult>Create(Request r,System.Security.Claims.ClaimsPrincipal p,UserManager<ApplicationUser>u,PublishingDbContext d,CancellationToken t){var actor=await u.GetUserAsync(p);var locale=await d.Locales.SingleOrDefaultAsync(x=>x.Code==r.Locale&&x.IsEnabled,t);if(actor is null)return Results.Unauthorized();if(locale is null||string.IsNullOrWhiteSpace(r.Title)||r.Title.Length>240||string.IsNullOrWhiteSpace(r.Claim)||r.Claim.Length>4000||!Uri.TryCreate(r.SourceUrl,UriKind.Absolute,out var url)||url.Scheme is not("http" or "https"))return Results.BadRequest();var item=new KnowledgeCandidate(locale,r.Title,r.Claim,url,r.AiAssisted,actor.Id,DateTimeOffset.UtcNow);d.Add(item);d.AuditLogs.Add(Audit(actor.Id,"knowledge.candidate_created",item.Id,new{r.AiAssisted}));await d.SaveChangesAsync(t);return Results.Created($"/api/v1/admin/knowledge/{item.Id}",new{item.Id});}
 private static async Task<IResult>Review(Guid id,bool approve,System.Security.Claims.ClaimsPrincipal p,UserManager<ApplicationUser>u,PublishingDbContext d,CancellationToken t){var actor=await u.GetUserAsync(p);var item=await d.KnowledgeCandidates.SingleOrDefaultAsync(x=>x.Id==id,t);if(actor is null)return Results.Unauthorized();if(item is null)return Results.NotFound();try{item.Review(approve,actor.Id,DateTimeOffset.UtcNow);}catch(InvalidOperationException ex){return Results.Conflict(new{message=ex.Message});}d.AuditLogs.Add(Audit(actor.Id,approve?"knowledge.approved":"knowledge.rejected",item.Id,null));await d.SaveChangesAsync(t);return Results.Ok(new{item.Id,status=item.Status.ToString()});}
 private static AuditLog Audit(Guid actor,string action,Guid id,object?details)=>new(actor,action,nameof(KnowledgeCandidate),id,details is null?null:JsonSerializer.Serialize(details),DateTimeOffset.UtcNow);private sealed record Request(string Locale,string Title,string Claim,string SourceUrl,bool AiAssisted);}
